use std::collections::BTreeSet;

let due: Vec<(String, u32)> = load_due();
let held: BTreeSet<String> = load_held();
let held_due: BTreeSet<&String> = due
    .iter()
    .map(|(id, _)| id)
    .filter(|id| held.contains(*id))
    .collect();
let rest: Vec<(String, u32)> = due
    .into_iter()
    .filter(|(id, _)| !held_due.contains(id))
    .collect();
